<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Teacher','Admin']); check_csrf(); if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['status']??[] as $sid=>$status){db()->prepare('INSERT INTO attendance(student_id,subject_id,date,status,method,confidence,marked_by) VALUES(?,?,?,?,?,?,?)')->execute([(int)$sid,(int)($_POST['subject_id']??1),$_POST['date']??date('Y-m-d'),$status,'Manual Encoding',100,$_SESSION['user_id']]); generate_prediction((int)$sid,false);} set_flash('success','Attendance saved.'); redirect('attendance.php');} $students=rows('SELECT s.*,u.full_name FROM students s JOIN users u ON u.id=s.user_id ORDER BY u.full_name'); render_header('Manage Attendance'); ?><div class="page-title"><div><h1>Manage Attendance</h1><p>Encode class attendance.</p></div></div><div class="panel"><form method="post"><?= csrf_field() ?><div class="row g-3 mb-3"><div class="col-md-4"><label>Date</label><input type="date" class="form-control" name="date" value="<?= date('Y-m-d') ?>"></div><div class="col-md-4"><label>Subject ID</label><input class="form-control" name="subject_id" value="1"></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Status</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?= e($s['student_no'].' - '.$s['full_name']) ?></td><td><select class="form-select" name="status[<?= e($s['id']) ?>]"><option>Present</option><option>Late</option><option>Absent</option><option>Excused</option></select></td></tr><?php endforeach; ?></tbody></table></div><button class="btn btn-primary">Save Attendance</button></form></div><?php render_footer(); ?>
